SELECT r.namespace, r.id, r.transition_id, r.phase, r.prior_revision, r.sequence, r.request_id, r.payload_json, r.created_at FROM (SELECT * FROM (SELECT a.* FROM chrome_retirement_audit a WHERE a.namespace=:Namespace AND a.transition_id=:TransitionID
) audit) r WHERE $criteria.CompositeIn("r", $Unsafe.ProjectCurrentAuditParentKeys($CurrentWriteChromeRetirement))